  "meaning": "නාභිය (පෙකණිය); රථ රෝදයේ මැද",
  "sutta_refs": "",
  "similar_words": "",
  "notes": [
   "මෙම පදයේ වරනැඟීම සද්දනීතිප්පකරණයේ පදමාලාවෙන් (8. ඉත්ථිලිඞ්ගනාමිකපදමාලා) ගන්නා ලදී.",
   "‘ඉමා ච නභ්‍යො සතරාජිචිත්තිතා’ ආදී පාළි ප්‍රයෝග දැකීමෙන් ‘නභ්‍යො, නභ්‍යා’ ආදී රූපද ගන්නා බව පදමාලාව කියයි.",
   "සාධන පියවර රූපසිද්ධි සූත්‍ර අනුව, රත්ති ශබ්දයේ සාධන ක්‍රමයට සමානව සකසා ඇත. ‘සද්දනීති පදමාලා රූපයකි’ ලෙස සටහන් රූප රූපසිද්ධියෙහි සෘජුව සාධනය නොවන, පදමාලාවෙහි පමණක් එන රූපයි."
  ],
