  "sutta_refs": "",
  "similar_words": "",
  "notes": [
   "මෙම පදයේ වරනැඟීම සද්දනීතිප්පකරණයේ පදමාලාවෙන් (10. ලිඞ්ගත්තයමිස්සකනාමිකපදමාලා) ගන්නා ලදී.",
   "‘ථියා ගුය්හං න සංසෙය්‍ය, ථීනං භාවො දුරාජානො’ ආදිය නිදර්ශන පද ලෙස පදමාලාව දක්වයි.",
   "සාධන පියවර රූපසිද්ධි සූත්‍ර අනුව, ඉත්ථී ශබ්දයේ සාධන ක්‍රමයට සමානව සකසා ඇත. ‘සද්දනීති පදමාලා රූපයකි’ ලෙස සටහන් රූප රූපසිද්ධියෙහි සෘජුව සාධනය නොවන, පදමාලාවෙහි පමණක් එන රූපයි."
  ],
