  "meaning": "ශ්‍රීය, ලක්ෂ්මිය (‘මා වුච්චති සිරී’)",
  "sutta_refs": "",
  "similar_words": "",
  "notes": [
   "මෙම පදයේ වරනැඟීම සද්දනීතිප්පකරණයේ පදමාලාවෙන් (10. ලිඞ්ගත්තයමිස්සකනාමිකපදමාලා) ගන්නා ලදී.",
   "‘මං සිරිං ධාරෙති විදධාති චාති මන්ධාතා’ ආදිය නිදර්ශන ලෙස පදමාලාව දක්වයි; ‘මාලිනී, මන්ධාතා’ යනු නිදර්ශන පදයි.",
   "සාධන පියවර රූපසිද්ධි සූත්‍ර අනුව, කඤ්ඤා ශබ්දයේ සාධන ක්‍රමයට සමානව සකසා ඇත. ‘සද්දනීති පදමාලා රූපයකි’ ලෙස සටහන් රූප රූපසිද්ධියෙහි සෘජුව සාධනය නොවන, පදමාලාවෙහි පමණක් එන රූපයි."
  ],
