  "meaning": "පෘථිවිය (‘කු වුච්චති පථවී’)",
  "sutta_refs": "",
  "similar_words": "",
  "notes": [
   "මෙම පදයේ වරනැඟීම සද්දනීතිප්පකරණයේ පදමාලාවෙන් (10. ලිඞ්ගත්තයමිස්සකනාමිකපදමාලා) ගන්නා ලදී.",
   "‘කුදාලො, කුමුදං, කුඤ්ජරො’ යනු නිදර්ශන පදයි — කුං පථවිං දාලයතීති කුදාලො.",
   "සාධන පියවර රූපසිද්ධි සූත්‍ර අනුව, යාගු ශබ්දයේ සාධන ක්‍රමයට සමානව සකසා ඇත. ‘සද්දනීති පදමාලා රූපයකි’ ලෙස සටහන් රූප රූපසිද්ධියෙහි සෘජුව සාධනය නොවන, පදමාලාවෙහි පමණක් එන රූපයි."
  ],
